package fr.cake.client;
import net.minecraft.client.Minecraft;import net.fabricmc.loader.api.FabricLoader;import java.nio.file.*;import java.util.*;import java.util.zip.*;
/** Optional Iris shader and photographic pack, installed locally with original licenses. */
public final class RealisticMode{
 public static String status="Disabled · enable to apply shader and 256x textures";private static Boolean last;private static boolean busy;private static boolean refresh;private static String failure="";
 public static boolean active(){try{return (boolean)Class.forName("net.irisshaders.iris.Iris").getMethod("isPackInUseQuick").invoke(null);}catch(Exception e){return false;}}
 public static boolean loading(){return busy;}public static void refresh(){refresh=true;}
 public static String selectedPack(){return CakeClient.settings.shaderPack==1?"MakeUp-UltraFast-9.6.zip":"Cake-Realis.zip";}
 private static Class<?> iris()throws Exception{return Class.forName("net.irisshaders.iris.Iris");}
 public static void tick(){var mc=Minecraft.getInstance();var s=CakeClient.settings;if(mc.level==null||busy||PvpCustomizer.loading())return;if(last==null){last=s.realistic?false:s.realismSaved||(packName().equals("Cake-Realis.zip")||packName().equals("MakeUp-UltraFast-9.6.zip"));status=s.realistic?"Applying lighting and textures…":"Disabled · enable to apply shader and 256x textures";}if(last==s.realistic&&!refresh)return;refresh=false;boolean wanted=s.realistic;last=wanted;busy=true;if(wanted)failure="";try{
  Path dir=FabricLoader.getInstance().getGameDir();install(selectedPack(),dir.resolve("shaderpacks"));install("Cake-Realism-256x.zip",dir.resolve("resourcepacks"));var cls=iris();var cfg=cls.getMethod("getIrisConfig").invoke(null);var c=cfg.getClass();
  if(wanted&&!s.realismSaved){s.previousShader=String.valueOf(((Optional<?>)c.getMethod("getShaderPackName").invoke(cfg)).orElse(null));s.previousShadersEnabled=(boolean)c.getMethod("areShadersEnabled").invoke(cfg);s.realismSaved=true;s.save();}
  c.getMethod("setShaderPackName",String.class).invoke(cfg,wanted?selectedPack():s.previousShader==null||s.previousShader.equals("null")?null:s.previousShader);c.getMethod("setShadersEnabled",boolean.class).invoke(cfg,wanted||s.previousShadersEnabled);c.getMethod("save").invoke(cfg);
  if(wanted){var props=new Properties();try(var zip=new ZipFile(dir.resolve("shaderpacks").resolve(selectedPack()).toFile())){var entry=zip.getEntry("shaders/shaders.properties");if(entry!=null){var full=new Properties();full.load(zip.getInputStream(entry));String profile=full.getProperty("profile."+(s.shaderPack==0?new String[]{"MEDIUM","HIGH","ULTRA"}:new String[]{"low","medium","high"})[s.realismQuality],"");for(String token:profile.split("\\s+")){if(token.isBlank()||token.startsWith("profile."))continue;String[] p=token.split("=",2);props.setProperty(p[0].replace("!",""),p.length==2?p[1]:p[0].startsWith("!")?"false":"true");}}}if(s.shaderPack==0){props.setProperty("PBR_TEXTURES","true");props.setProperty("DOF","false");props.setProperty("MOTION_BLUR","false");props.setProperty("EXPOSURE",new String[]{"0.8","0.9","1.0","1.1","1.2"}[(int)Math.round(s.realismExposure*4)]);props.setProperty("BLOOM_STRENGTH",new String[]{"0.5","0.75","1.0","1.5","2.0"}[(int)Math.round(s.realismBloom*4)]);props.setProperty("PUDDLE_AMOUNT",new String[]{"0.5","0.75","1.0","1.25","1.5"}[(int)Math.round(s.realismRain*4)]);props.setProperty("RAIN_OPACITY",new String[]{"0.5","0.75","1.0","1.5","2.0"}[(int)Math.round(s.realismRain*4)]);props.setProperty("SATURATION",new String[]{"1.0","1.1","1.2"}[s.realismLook]);props.setProperty("TONEMAP",s.realismLook==1?"1":"0");props.setProperty("SHARPENING",s.realismLook==2?"0.6":"0.4");}else{props.setProperty("DOF","false");props.setProperty("MOTION_BLUR","false");props.setProperty("COLOR_SCHEME",new String[]{"1","2","3"}[s.realismLook]);}cls.getMethod("queueShaderPackOptionsFromProperties",Properties.class).invoke(null,props);}
  var repo=mc.getResourcePackRepository();repo.reload();var selected=new ArrayList<>(repo.getSelectedIds());selected.removeIf(x->x.endsWith("Cake-Realism-256x.zip"));if(wanted){String id=repo.getAvailableIds().stream().filter(x->x.endsWith("Cake-Realism-256x.zip")).findFirst().orElseThrow();selected.add(id);}repo.setSelected(selected);mc.options.resourcePacks.clear();for(var p:repo.getSelectedPacks())if(!p.isFixedPosition())mc.options.resourcePacks.add(p.getId());mc.options.save();status="Applying lighting and textures…";
  mc.reloadResourcePacks().whenComplete((v,error)->mc.execute(()->{try{if(error!=null)throw new RuntimeException(error);iris().getMethod("reload").invoke(null);var stored=(Optional<?>)iris().getMethod("getStoredError").invoke(null);if(wanted&&stored.isPresent())throw new IllegalStateException("Shader compile failed",(Throwable)stored.get());status=wanted?selectedPack()+" + XsRealism 256x active":failure.isEmpty()?"Previous shader restored":failure;if(!wanted){s.realismSaved=false;s.save();}}catch(Exception e){failure="Realism failed: "+rootMessage(e)+" · config/cake-client/realism-error.txt";status=failure;s.realistic=false;last=true;report(e);CakeClient.LOG.error("Realistic mode",e);}finally{busy=false;Settings.revision++;}}));
 }catch(Exception e){busy=false;s.realistic=false;last=true;failure="Realism failed: "+rootMessage(e)+" · config/cake-client/realism-error.txt";status=failure;report(e);CakeClient.LOG.error("Realistic mode",e);}}
 private static String rootMessage(Throwable e){while(e.getCause()!=null)e=e.getCause();return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}
 private static void report(Exception e){try{Files.createDirectories(Settings.DIR);var text=new java.io.StringWriter();e.printStackTrace(new java.io.PrintWriter(text));Files.writeString(Settings.DIR.resolve("realism-error.txt"),text.toString());}catch(Exception ignored){}}
 private static String packName(){try{return String.valueOf(iris().getMethod("getCurrentPackName").invoke(null));}catch(Exception e){return "";}}
 private static void install(String name,Path directory)throws Exception{Files.createDirectories(directory);Path target=directory.resolve(name),tmp=directory.resolve(name+".cake.tmp");try(var in=RealisticMode.class.getResourceAsStream("/assets/cakeclient/realism/"+name)){if(in==null)throw new java.io.IOException(name);Files.copy(in,tmp,StandardCopyOption.REPLACE_EXISTING);}if(!Files.exists(target)||Files.mismatch(tmp,target)!=-1)Files.move(tmp,target,StandardCopyOption.REPLACE_EXISTING);else Files.delete(tmp);}
}
